using Microsoft.EntityFrameworkCore;using RegistrationService.Data;using RegistrationService.DTOs;using RegistrationService.Entities;using RegistrationService.Events;using RegistrationService.Messaging;namespace RegistrationService.Endpoints;public static class RegistrationEndpoints{public static void MapRegistrationEndpoints(this WebApplication app){app.MapGet("/health",()=>Results.Ok(new{service="registration",status="healthy"}));app.MapGet("/api/registrations",async(RegistrationDbContext db,CancellationToken ct)=>Results.Ok(await db.Registrations.AsNoTracking().OrderByDescending(x=>x.CreatedAtUtc).ToListAsync(ct)));app.MapGet("/api/registrations/{id:int}",async Task<IResult>(int id,RegistrationDbContext db,CancellationToken ct)=>{var item=await db.Registrations.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id,ct);return item is null?Results.NotFound(new{message="Registration not found."}):Results.Ok(item);});app.MapPost("/api/registrations",async Task<IResult>(CreateRegistrationRequest r,RegistrationDbContext db,RegistrationEventPublisher publisher,CancellationToken ct)=>{if(string.IsNullOrWhiteSpace(r.CandidateNumber)||string.IsNullOrWhiteSpace(r.CandidateName)||string.IsNullOrWhiteSpace(r.ExamSession)||r.Subjects is null||r.Subjects.Count==0)return Results.BadRequest(new{message="Candidate number, candidate name, exam session, and at least one subject are required."});var number=r.CandidateNumber.Trim().ToUpperInvariant();var session=r.ExamSession.Trim();if(await db.Registrations.AnyAsync(x=>x.CandidateNumber==number&&x.ExamSession==session,ct))return Results.Conflict(new{message="This candidate already has a registration for that exam session."});var subjects=r.Subjects.Select(x=>x.Trim()).Where(x=>x.Length>0).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();if(subjects.Length==0)return Results.BadRequest(new{message="Provide at least one non-empty subject."});var item=new ExamRegistration{CandidateNumber=number,CandidateName=r.CandidateName.Trim(),ExamSession=session,Subjects=string.Join(",",subjects),CreatedAtUtc=DateTime.UtcNow};db.Registrations.Add(item);await db.SaveChangesAsync(ct);await publisher.PublishAsync(new RegistrationCreatedEvent(item.Id,item.CandidateNumber,item.CandidateName,item.ExamSession,item.Subjects,item.CreatedAtUtc),ct);return Results.Created($"/api/registrations/{item.Id}",item);});}}